//! Known answers (`packages/vectors/known_answers.json`, generated by `@merces/sdk`) recomputed with
//! the code the programs run: the §1.3 encodings and domain, every §1.4 signed message (pre-image,
//! digest and secp256k1 recovery through the `secp256k1_recover` path of `merces-onchain`), the
//! Poseidon commitments behind tier-1 binding, periods and trading days, the pause countdown, the
//! tagged `year_gross` ring, FX normalisation and the `mulDiv` rounding points.

use merces_common::encoding::{
    amend_message, commitment_preimage, domain_preimage, extinguish_message, fx_message,
    fx_pair_id_preimage, pause_message, report_message, trueup_message, u64_to_be32,
};
use merces_common::fx::normalize;
use merces_common::redemption::{year_gross_add, year_gross_at, YearGross};
use merces_common::status::{paused_within, unpaused, Pause};
use merces_common::time::{
    days_in_period, period_end, period_of, period_start, trading_days_in_period,
};
use merces_common::{div_ceil, mul_div};
use merces_onchain::{keccak, poseidon2, poseidon5, recover_eth_address};
use merces_tests::zkfix::{hex32, hex_bytes, vector_path};
use serde_json::Value;

fn known() -> Value {
    let text = std::fs::read_to_string(vector_path("known_answers.json")).expect("known answers");
    serde_json::from_str(&text).expect("json")
}

fn s(v: &Value) -> &str {
    v.as_str()
        .unwrap_or_else(|| panic!("string expected, got {v}"))
}

fn dec(v: &Value) -> u64 {
    match v {
        Value::String(x) => x.parse().unwrap(),
        Value::Number(n) => n.as_u64().unwrap(),
        _ => panic!("number expected, got {v}"),
    }
}

/// A decimal field element (< 2^256) as 32 big-endian bytes.
fn field(v: &Value) -> [u8; 32] {
    let text = match v {
        Value::String(x) => x.clone(),
        Value::Number(n) => n.to_string(),
        _ => panic!("field expected"),
    };
    let mut out = [0u8; 32];
    for ch in text.bytes() {
        let mut carry = u32::from(ch - b'0');
        for byte in out.iter_mut().rev() {
            let v = u32::from(*byte) * 10 + carry;
            *byte = (v & 0xff) as u8;
            carry = v >> 8;
        }
        assert_eq!(carry, 0);
    }
    out
}

fn hex20(v: &Value) -> [u8; 20] {
    let b = hex_bytes(s(v));
    let mut out = [0u8; 20];
    out.copy_from_slice(&b);
    out
}

#[test]
fn keccak_and_poseidon() {
    let k = known();
    for case in k["keccak256"].as_array().unwrap() {
        assert_eq!(
            keccak(&[&hex_bytes(s(&case["input"]))]),
            hex32(s(&case["output"]))
        );
    }
    for case in k["poseidon2"].as_array().unwrap() {
        let i = case["inputs"].as_array().unwrap();
        assert_eq!(
            poseidon2(&field(&i[0]), &field(&i[1])).unwrap(),
            hex32(s(&case["outputHex"]))
        );
    }
    for case in k["poseidon5"].as_array().unwrap() {
        let i: Vec<[u8; 32]> = case["inputs"]
            .as_array()
            .unwrap()
            .iter()
            .map(field)
            .collect();
        let inputs = [i[0], i[1], i[2], i[3], i[4]];
        assert_eq!(poseidon5(&inputs).unwrap(), hex32(s(&case["outputHex"])));
    }
    // terms commitments: Poseidon(5)(theta, r_wad, currency, indexing, salt) — the tier-1 check of
    // `create_series`
    for case in k["termsCommitments"].as_array().unwrap() {
        let inputs = [
            u64_to_be32(dec(&case["theta"])),
            u64_to_be32(dec(&case["rWad"])),
            u64_to_be32(dec(&case["currencyCode"])),
            u64_to_be32(dec(&case["indexingRule"])),
            field(&case["termsSalt"]),
        ];
        assert_eq!(
            poseidon5(&inputs).unwrap(),
            hex32(s(&case["commitmentHex"]))
        );
    }
    for case in k["incomeCommitments"].as_array().unwrap() {
        assert_eq!(
            poseidon2(
                &u64_to_be32(dec(&case["incomeYtd"])),
                &field(&case["incomeSalt"])
            )
            .unwrap(),
            hex32(s(&case["commitmentHex"]))
        );
    }
    // tier-1 binding: Poseidon(2)(ytd_at_end, 0)
    for case in k["routerIncomeCommitments"].as_array().unwrap() {
        assert_eq!(
            poseidon2(&u64_to_be32(dec(&case["ytdAtEnd"])), &[0u8; 32]).unwrap(),
            hex32(s(&case["commitmentHex"]))
        );
    }
    assert_eq!(
        hex32(s(&k["constants"]["ZERO_INCOME_COMMITMENT_HEX"])),
        merces_protocol::income::ZERO_INCOME_COMMITMENT
    );
}

#[test]
fn domains_bid_commitments_and_pair_ids() {
    let k = known();
    for d in k["domains"].as_array().unwrap() {
        let kind = u8::try_from(dec(&d["chainKind"])).unwrap();
        let pre = domain_preimage(kind, dec(&d["chainId"]), &hex32(s(&d["registry"])));
        assert_eq!(pre.as_bytes(), hex_bytes(s(&d["preimage"])).as_slice());
        assert_eq!(keccak(&[pre.as_bytes()]), hex32(s(&d["domain"])));
    }
    for b in k["bidCommitments"].as_array().unwrap() {
        let pre = commitment_preimage(
            dec(&b["price"]),
            dec(&b["quantity"]),
            &hex32(s(&b["salt"])),
            &hex32(s(&b["wallet"])),
        );
        assert_eq!(pre.as_bytes(), hex_bytes(s(&b["preimage"])).as_slice());
        assert_eq!(keccak(&[pre.as_bytes()]), hex32(s(&b["commitment"])));
    }
    for p in k["fx"]["pairIds"].as_array().unwrap() {
        let pre = fx_pair_id_preimage(&hex32(s(&p["feedId"])), p["inverted"].as_bool().unwrap());
        assert_eq!(keccak(&[pre.as_bytes()]), hex32(s(&p["pairId"])));
    }
    // a Solana wallet is its 32-byte key (SPEC §1.3)
    for w in k["wallets"].as_array().unwrap() {
        if s(&w["kind"]) == "solana" {
            let key: anchor_lang::prelude::Pubkey = s(&w["input"]).parse().unwrap();
            assert_eq!(key.to_bytes(), hex32(s(&w["wallet"])));
        }
    }
}

/// Every §1.4 message: the pre-image built by `merces_common::encoding` equals the SDK's byte for
/// byte, its keccak is the digest, and the published signature recovers to the signer's address
/// through `merces_onchain::recover_eth_address` (the code path of every attestation check).
#[test]
fn signed_messages_recover_to_their_signers() {
    let k = known();
    let domains: Vec<(String, [u8; 32])> = k["domains"]
        .as_array()
        .unwrap()
        .iter()
        .map(|d| (s(&d["name"]).to_string(), hex32(s(&d["domain"]))))
        .collect();
    let mut checked = 0;
    for m in k["messages"].as_array().unwrap() {
        let domain = domains
            .iter()
            .find(|(n, _)| n == s(&m["domain"]))
            .map(|(_, d)| *d)
            .unwrap();
        let series_key = if s(&m["domain"]).starts_with("solana") {
            hex32(s(&k["seriesKeys"]["solana"]["key"]))
        } else {
            hex32(s(&k["seriesKeys"]["evm"]["key"]))
        };
        let f = &m["fields"];
        let pre = match s(&m["kind"]) {
            "REPORT" => report_message(
                &domain,
                &series_key,
                u32::try_from(dec(&f["period"])).unwrap(),
                &hex32(s(&f["priorIncomeCommitment"])),
                &hex32(s(&f["incomeCommitment"])),
                u8::try_from(dec(&f["tier"])).unwrap(),
                f["liquidityEvent"].as_bool().unwrap(),
            ),
            "FX" => fx_message(
                &domain,
                &series_key,
                u32::try_from(dec(&f["period"])).unwrap(),
                dec(&f["fxRateWad"]),
            ),
            "AMEND" => amend_message(
                &domain,
                &series_key,
                dec(&f["amendmentNonce"]),
                &hex32(s(&f["newTermsCommitment"])),
                dec(&f["newCapMultipleWad"]),
            ),
            "PAUSE" => pause_message(
                &domain,
                &series_key,
                dec(&f["pauseNonce"]),
                dec(&f["pauseEnd"]),
            ),
            "EXTINGUISH" => extinguish_message(&domain, &series_key, dec(&f["extinguishNonce"])),
            "TRUEUP" => trueup_message(
                &domain,
                &series_key,
                dec(&f["trueupNonce"]),
                u16::try_from(dec(&f["year"])).unwrap(),
                s(&f["adjustment"]).parse::<i64>().unwrap(),
                dec(&f["attestationTs"]),
            ),
            other => panic!("unknown message kind {other}"),
        };
        assert_eq!(
            pre.as_bytes(),
            hex_bytes(s(&m["preimage"])).as_slice(),
            "{} pre-image",
            s(&m["kind"])
        );
        assert_eq!(pre.as_bytes().len() as u64, dec(&m["preimageLength"]));
        let digest = keccak(&[pre.as_bytes()]);
        assert_eq!(digest, hex32(s(&m["digest"])), "{} digest", s(&m["kind"]));
        let sig = hex_bytes(s(&m["signature"]));
        assert_eq!(
            recover_eth_address(&digest, &sig).unwrap(),
            hex20(&m["signerAddress"]),
            "{} signer",
            s(&m["kind"])
        );
        // a high-s twin of the same signature is refused (low-s rule, SPEC §1.4)
        let mut high = sig.clone();
        let n: [u8; 32] =
            hex32("0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141");
        let mut s_val = [0u8; 32];
        s_val.copy_from_slice(&sig[32..64]);
        let mut borrow = 0i16;
        for i in (0..32).rev() {
            let d = i16::from(n[i]) - i16::from(s_val[i]) - borrow;
            high[32 + i] = d.rem_euclid(256) as u8;
            borrow = i16::from(d < 0);
        }
        high[64] = if sig[64] == 27 { 28 } else { 27 };
        assert!(recover_eth_address(&digest, &high).is_err());
        checked += 1;
    }
    assert_eq!(checked, k["messages"].as_array().unwrap().len());
    assert!(checked >= 12);
}

#[test]
fn test_keys_match_their_addresses() {
    let k = known();
    for key in k["testKeys"].as_array().unwrap() {
        let signer = merces_tests::sig::EthSigner::from_private_key(&hex32(s(&key["privateKey"])));
        assert_eq!(signer.addr, hex20(&key["address"]));
    }
}

#[test]
fn periods_pauses_year_ring_fx_and_fixed_point() {
    let k = known();
    for p in k["periods"].as_array().unwrap() {
        let pid = u32::try_from(dec(&p["periodId"])).unwrap();
        assert_eq!(period_of(dec(&p["timestamp"])).unwrap(), pid);
        assert_eq!(period_start(pid).unwrap(), dec(&p["periodStart"]));
        assert_eq!(period_end(pid).unwrap(), dec(&p["periodEnd"]));
        assert_eq!(days_in_period(pid).unwrap(), dec(&p["daysInPeriod"]));
        assert_eq!(
            trading_days_in_period(pid).unwrap(),
            dec(&p["tradingDaysInPeriod"])
        );
    }
    for e in k["periodIdExamples"].as_array().unwrap() {
        let pid = dec(&e["year"]) * 4 + dec(&e["quarter"]) - 1;
        assert_eq!(pid, dec(&e["periodId"]));
    }
    let pauses: Vec<Pause> = k["pauses"]["pauseList"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| Pause {
            start: dec(&p["start"]),
            end: dec(&p["end"]),
        })
        .collect();
    for c in k["pauses"]["cases"].as_array().unwrap() {
        let (a, b, now) = (dec(&c["a"]), dec(&c["b"]), dec(&c["now"]));
        assert_eq!(paused_within(&pauses, a, b, now), dec(&c["pausedWithin"]));
        assert_eq!(unpaused(&pauses, a, b, now), dec(&c["unpaused"]));
    }
    let mut ring = [YearGross::default(); 4];
    for add in k["yearGross"]["adds"].as_array().unwrap() {
        year_gross_add(
            &mut ring,
            u32::try_from(dec(&add["year"])).unwrap(),
            s(&add["incWad"]).parse().unwrap(),
        )
        .unwrap();
    }
    for (slot, exp) in ring.iter().zip(k["yearGross"]["slots"].as_array().unwrap()) {
        assert_eq!(u64::from(slot.year), dec(&exp["year"]));
        assert_eq!(slot.gross_wad, s(&exp["grossWad"]).parse::<u128>().unwrap());
    }
    for r in k["yearGross"]["reads"].as_array().unwrap() {
        assert_eq!(
            year_gross_at(&ring, u32::try_from(dec(&r["year"])).unwrap()),
            s(&r["grossWad"]).parse::<u128>().unwrap()
        );
    }
    for n in k["fx"]["normalize"].as_array().unwrap() {
        let price: i128 = s(&n["price"]).parse().unwrap();
        let expo = i32::try_from(n["expo"].as_i64().unwrap()).unwrap();
        let expected = n.get("rateWad").and_then(|r| r.as_str());
        match (i64::try_from(price), expected) {
            (Ok(p), Some(rate)) => match rate.parse::<u64>() {
                Ok(r) => assert_eq!(normalize(p, expo).unwrap(), r, "normalize {price}e{expo}"),
                // a rate above u64 cannot be a valid `fx_avg_wad` (SPEC §1.1)
                Err(_) => assert!(normalize(p, expo).is_err()),
            },
            // a Pyth price is an i64; anything larger is unrepresentable on Solana
            (Err(_), _) => {}
            (Ok(p), None) => assert!(normalize(p, expo).is_err()),
        }
    }
    for f in k["fixedPoint"].as_array().unwrap() {
        let (a, b, c) = (
            s(&f["a"]).parse::<u128>().unwrap(),
            s(&f["b"]).parse::<u128>().unwrap(),
            s(&f["c"]).parse::<u128>().unwrap(),
        );
        let r = s(&f["result"]).parse::<u128>().unwrap();
        match s(&f["op"]) {
            "mulDiv" => assert_eq!(mul_div(a, b, c).unwrap(), r),
            "mulDivCeil" => assert_eq!(div_ceil(a * b, c).unwrap(), r),
            other => panic!("unknown op {other}"),
        }
    }
}
